use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-wnaf-screen176";
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn n(v:&Value,k:&str)->u64{v[k].as_u64().unwrap()}
fn main(){assert!(!std::path::Path::new(&format!("{R}/review.json")).exists());let p=read(&format!("{R}/plan.json"));let mut pins=0;for(path,h)in read(&format!("{R}/pins.json")).as_object().unwrap(){assert_eq!(hash(path),h.as_str().unwrap());pins+=1;}let mut commands=0;for step in p["steps"].as_array().unwrap(){let root=format!("{R}/runs/{}",step["name"].as_str().unwrap());let e=read(&format!("{root}/exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{root}/{stream}.log")),e[format!("{stream}_sha256")].as_str().unwrap());}let c=read(&format!("{root}/command.json"));assert!(c["argv"].as_array().unwrap().ends_with(step["argv"].as_array().unwrap()));commands+=1;}assert_eq!(commands,2);assert_eq!(read(&format!("{R}/runs/result.json"))["status"],"complete");assert_eq!(read(&format!("{R}/runs/attempt-0.json"))["resume"],false);
let a=read(&format!("{R}/analysis.json"));assert_eq!(a["complete"],true);let mut rebuilt=BTreeMap::new();for key in["original_radix_all_including_indexed_top_hypothetical_dense","original_ordinary_excluding_indexed_top","candidate_wnaf"]{let v=&a[key];let rows=v["rows"].as_array().unwrap();let mut arrivals=0;let mut first=0;let mut merges=0;let mut fold=0;let mut active=0;for(i,row)in rows.iter().enumerate(){assert_eq!(n(row,"position"),i as u64);arrivals+=n(row,"arrivals");first+=row["occupied_per_part"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).sum::<u64>();merges+=n(row,"overlap_slots");let max=n(row,"dense_fold_slots");let f=if max>0{2*(max-1)}else{0};assert_eq!(f,n(row,"dense_fold_generic_model_adds"));fold+=f;active+=u64::from(n(row,"arrivals")>0);}assert_eq!(arrivals,n(v,"arrivals"));assert_eq!(first,n(v,"first_assignments"));assert_eq!(merges,n(v,"part_merges"));assert_eq!(fold,n(v,"dense_weighted_fold_model_adds"));assert_eq!(arrivals-first,n(v,"post_first_arrivals"));let total=arrivals-first+merges+fold;assert_eq!(total,n(v,"generic_addition_model_total"));rebuilt.insert(key,json!({"arrivals":arrivals,"first_assignments":first,"part_merges":merges,"dense_weighted_fold_model_adds":fold,"generic_addition_model_total":total,"active_positions":active}));}
let ordinary=&rebuilt["original_ordinary_excluding_indexed_top"];let full=&rebuilt["original_radix_all_including_indexed_top_hypothetical_dense"];let candidate=&rebuilt["candidate_wnaf"];assert_eq!(n(full,"arrivals"),n(ordinary,"arrivals")+n(&a,"original_indexed_top_terms"));assert_eq!(n(ordinary,"arrivals"),558614);assert_eq!(n(ordinary,"first_assignments"),40960);assert_eq!(n(&a,"original_indexed_top_terms"),55277);assert_eq!(n(&a,"actual_components_reconstructed_each_recipe"),60178);assert_eq!(n(&a,"additional_boundary_random_identity_cases"),20000);
// The capture helper's native-selection boolean compared candidate full work
// to ordinary-only radix work. Preserve it, and use both complete counterfactual
// geometries for the model comparison. Neither is native indexed-top timing.
let old=n(candidate,"generic_addition_model_total")<n(ordinary,"generic_addition_model_total");assert_eq!(a["eager_generic_addition_model_selects_native"],old);let corrected=n(candidate,"generic_addition_model_total")<n(full,"generic_addition_model_total");assert!(!old&&!corrected);let output=json!({"review_passed":true,"scope":"Independent reconstruction of aggregate rows and command/source identities; no second scalar scan, recoding test or curve oracle", "source_input_pins":pins,"successful_workflow_commands":commands,"models_rebuilt":rebuilt,"candidate_over_full_dense_radix":n(candidate,"generic_addition_model_total")as f64/n(full,"generic_addition_model_total")as f64,"candidate_arrivals_over_all_radix":n(candidate,"arrivals")as f64/n(full,"arrivals")as f64,"initial_partial_comparator_retained":true,"complete_dense_model_selects_native":corrected,"decision_unchanged_no_native_selection":true,"actual_accepted_indexed_top_cost_not_established":true,"no_latency_or_all_NAF_lowerbound":true,"new_proofs":0,"proof_ledger":30708,"adopted":false,"goal_achieved":false});fs::write(format!("{R}/review.json"),serde_json::to_vec_pretty(&output).unwrap()).unwrap();println!("ReviewPASS {pins}pins/2commands/allaggregates;fullcounterfactualradixvsNAF model{}%; no nativescreen selection,latency orproofclaim",100.*(output["candidate_over_full_dense_radix"].as_f64().unwrap()-1.));}
